// Employee meals: incremental writeoff during the day, BUKHARA test.
(function(){
 state.mealDishes=[];state.mealSearch='';state.mealSummary=[];state.mealBusy=false;
 function actor(){return localStorage.getItem('stolovaya:employee-name')||'Буфетчик'}
 const bh=homeScreen;homeScreen=function(){let h=bh();if(state.point!=='BUKHARA')return h;const disabled=state.home?.submitted||state.home?.dayClosed?'disabled':'';return h.replace('</section>',`<button type="button" id="employee-meal-open" ${disabled}><span>🍽</span><div><b>Питание</b></div></button></section>`)};
 async function loadMeal(){state.mealBusy=true;render();try{const [d,s]=await Promise.all([rpc('public_kitchen_supply_dishes',{p_token:state.token,p_point_code:state.point}),rpc('public_employee_meal_summary',{p_token:state.token,p_point_code:state.point,p_business_date:businessDate()})]);state.mealDishes=d||[];state.mealSummary=s||[]}finally{state.mealBusy=false;render()}}
 function found(){const q=state.mealSearch.trim().toLowerCase();if(q.length<2)return[];return state.mealDishes.filter(x=>clean(x.name).toLowerCase().includes(q)||String(x.code||'').toLowerCase().includes(q)).slice(0,12)}
 function screen(){const f=found();return `${header()}${back('Питание')}<section class="question-card"><h2>Бесплатная еда сотрудников</h2><p>Каждое сохранение сразу уменьшает доступный остаток. Можно добавлять сколько угодно раз в течение дня.</p></section>${state.mealSummary.length?`<section class="question-card"><b>Уже занесено сегодня</b>${state.mealSummary.map(x=>`<div class="meal-total"><span>${esc(clean(x.dish_name))}</span><b>${n(x.total_qty)}</b></div>`).join('')}</section>`:''}<div class="kitchen-picker"><input id="meal-search" class="search" autocomplete="off" placeholder="Введите минимум 2 буквы" value="${esc(state.mealSearch)}">${state.mealSearch.trim().length>=2?`<div class="kitchen-suggestions">${f.length?f.map(x=>`<button type="button" data-meal-pick="${x.dishId}"><b>${esc(clean(x.name))}</b><small>${esc(x.group||'')}</small></button>`).join(''):'<div class="kitchen-no-match">Ничего не найдено</div>'}</div>`:''}</div>${state.mealBusy?'<div class="notice">Загрузка…</div>':''}${state.message?`<p class="toast">${esc(state.message)}</p>`:''}`}
 async function add(id){const d=state.mealDishes.find(x=>x.dishId===id);if(!d)return;const raw=prompt(`${clean(d.name)}\nСколько добавить в питание?`,'1');if(raw===null)return;const qty=n(String(raw).replace(',','.'));if(!(qty>0))return;state.mealBusy=true;state.message='';render();try{const r=await rpc('public_add_employee_meal',{p_token:state.token,p_point_code:state.point,p_dish_id:id,p_quantity:qty,p_actor:actor(),p_business_date:businessDate()});state.mealSearch='';await loadPoint();await loadMeal();state.message=`Сохранено: +${qty}. Всего сегодня: ${r.total}. Доступно осталось: ${r.available}.`}catch(e){state.message=e.message||'Не удалось сохранить';state.mealBusy=false;render()}}
 const br=render;render=function(){if(state.screen==='employee-meal'){app.innerHTML=screen();bind();return}br()};
 const bb=bind;bind=function(){bb();document.getElementById('employee-meal-open')?.addEventListener('click',()=>{state.screen='employee-meal';state.message='';render();loadMeal()});const s=document.getElementById('meal-search');if(s)s.oninput=e=>{state.mealSearch=e.target.value;render()};document.querySelectorAll('[data-meal-pick]').forEach(b=>b.onclick=()=>add(b.dataset.mealPick))};
 const st=document.createElement('style');st.textContent='.meal-total{display:flex;justify-content:space-between;gap:12px;padding:9px 0;border-bottom:1px solid #e7e5dc}.meal-total:last-child{border-bottom:0}';document.head.appendChild(st);
})();